-- AnyBike 10 November 2026: 13 exact identities across four makes.
-- Zero public content writes. These short sections are sourced private research,
-- not completed 20-section guides. Publication and ID safety gates are strict.
DO $$
DECLARE matched integer; inserted integer; before_pub integer; after_pub integer;
BEGIN
 SELECT count(*) INTO before_pub FROM public.motorcycle_universal_published_sections_v1;
 WITH wanted(id,make,model) AS (VALUES (559,'Moto Guzzi','Stelvio'),
(560,'Moto Guzzi','V7 Special'),
(561,'Moto Guzzi','V7 Stone'),
(217,'Moto Guzzi','V85 TT'),
(563,'Moto Guzzi','V9 Bobber'),
(3,'Aprilia','RSV4'),
(329,'Aprilia','Tuareg 660'),
(795,'Aprilia','RS 125'),
(331,'Aprilia','Tuono V4'),
(528,'KTM','890 Adventure'),
(526,'KTM','790 Adventure'),
(951,'Royal Enfield','Bullet 500'),
(960,'Royal Enfield','Classic 500'))
 SELECT count(*) INTO matched FROM wanted w
 JOIN public.motorcycle_catalog_models m ON m.id=w.id AND m.manufacturer=w.make AND m.model=w.model
 WHERE NOT EXISTS(SELECT 1 FROM public.motorcycle_universal_page_sections_v1 s WHERE s.entity_type='model' AND s.model_id=w.id)
 AND NOT EXISTS(SELECT 1 FROM public.motorcycle_catalog_model_aliases a WHERE a.alias_model_id=w.id AND a.review_status<>'approved')
 AND EXISTS(SELECT 1 FROM public.motorcycle_catalog_manufacturers r WHERE r.display_name=w.make);
 IF matched<>13 THEN RAISE EXCEPTION 'Private research batch aborted: expected 13 exact unstaged identities, got %',matched; END IF;
 INSERT INTO public.motorcycle_universal_page_sections_v1
 (entity_type,manufacturer_id,model_id,section_number,section_title,content,editorial_status,source_reference,published_at)
 SELECT 'model',NULL,v.model_id,v.section_number,v.section_title,v.content,'draft','factory_source_index:'||v.source_url,NULL
 FROM (VALUES (559,1,'Model introduction','{"summary":"The Stelvio is Moto Guzzi''s adventure-touring motorcycle, positioned for extended travel and varied road conditions.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/news/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/news/'),
(559,7,'Documented model and source history','{"summary":"Moto Guzzi''s 2026 range update describes a 1,042 cc V-twin, 19-inch front wheel and electrically adjustable windscreen for the 2026 Stelvio. These are 2026-family details, not all historic Stelvios.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/news/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/news/'),
(560,1,'Model introduction','{"summary":"The V7 Special is a classically styled version of Moto Guzzi''s V7 roadster family.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/eicma/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/eicma/'),
(560,7,'Documented model and source history','{"summary":"Moto Guzzi lists the V7 family in its 2026/EICMA manufacturer range; edition-specific paint and technical details must be confirmed separately from the V7 Stone and later anniversary editions.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/eicma/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/eicma/'),
(561,1,'Model introduction','{"summary":"The V7 Stone is the pared-back roadster version of Moto Guzzi''s current V7 family.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/news/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/news/'),
(561,7,'Documented model and source history','{"summary":"Moto Guzzi''s 2026 company range announcement identifies a new Sabbia Camu colour for the 2026 V7 Stone and describes its 850 cc twin-cylinder platform.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/news/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/news/'),
(217,1,'Model introduction','{"summary":"The V85 TT is Moto Guzzi''s mid-capacity adventure motorcycle, with travel-focused ergonomic and chassis equipment.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/news/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/news/'),
(217,7,'Documented model and source history','{"summary":"Moto Guzzi''s official 2026 range report distinguishes the V85 TT, V85 TT Travel and V85 Strada; their wheels and cornering-ABS equipment cannot be treated as interchangeable.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/landing-page/news/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/landing-page/news/'),
(563,1,'Model introduction','{"summary":"The V9 Bobber is Moto Guzzi''s factory bobber-style road motorcycle in the manufacturer''s V9 family.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/moto-guzzi-world/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/moto-guzzi-world/'),
(563,7,'Documented model and source history','{"summary":"Moto Guzzi''s company news archive records a V9 model-year 2021 update published on 11 January 2021. Source scope is V9 family-level, not detailed Bobber trim specifications.","source_name":"Moto Guzzi official documentary material","source_url":"https://www.motoguzzi.com/en_EN/moto-guzzi-world/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.motoguzzi.com/en_EN/moto-guzzi-world/'),
(3,1,'Model introduction','{"summary":"The RSV4 is Aprilia''s four-cylinder superbike family, with road and Factory variants.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(3,7,'Documented model and source history','{"summary":"Aprilia''s 3 March 2022 manufacturer range announcement records new black graphics for RSV4 Factory, distinct from the base RSV4; the source does not establish a universal original launch year.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(329,1,'Model introduction','{"summary":"Aprilia''s Tuareg 660 is an adventure motorcycle using the manufacturer''s middleweight twin-cylinder platform.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(329,7,'Documented model and source history','{"summary":"Aprilia''s March 2022 range announcement states the Tuareg 660 was already available at dealerships from late 2021. Market availability cannot be assumed identical worldwide.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(795,1,'Model introduction','{"summary":"The RS 125 is Aprilia''s small-capacity sport-road model within the RS family.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(795,7,'Documented model and source history','{"summary":"Aprilia''s official 2022 range release describes an RS 125 GP Replica version with MotoGP-inspired livery; it is a distinct edition, not standard equipment across the model family.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(331,1,'Model introduction','{"summary":"The Tuono V4 is Aprilia''s large-capacity V4 naked-sport motorcycle family.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(331,7,'Documented model and source history','{"summary":"Aprilia''s March 2022 release distinguishes the Tuono V4 Factory black graphics from the standard Tuono V4; original launch chronology requires other period-specific documentary sources.","source_name":"Aprilia official documentary material","source_url":"https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.aprilia.com/kr_KO/aprilia-world/news-aprilia/new-2022-aprilia-products-finally-land-at-dealerships/'),
(528,1,'Model introduction','{"summary":"The KTM 890 Adventure is a middleweight travel and adventure model using KTM''s parallel-twin LC8c powertrain.","source_name":"KTM official documentary material","source_url":"https://www.ktm.com/en-int/890-adventure-press-kit-2023.html","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.ktm.com/en-int/890-adventure-press-kit-2023.html'),
(528,7,'Documented model and source history','{"summary":"KTM''s 2023 factory press kit documents the revised standard 890 Adventure with an 889 cc engine and upgraded bodywork, ergonomics and instrumentation. R and Rally variants are different.","source_name":"KTM official documentary material","source_url":"https://www.ktm.com/en-int/890-adventure-press-kit-2023.html","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.ktm.com/en-int/890-adventure-press-kit-2023.html'),
(526,1,'Model introduction','{"summary":"The 790 Adventure is KTM''s middleweight adventure tourer, distinct from the higher-specification 790 Adventure R.","source_name":"KTM official documentary material","source_url":"https://press.ktm.com/news-new-adventures-start-now-with-ktm?id=80395&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://press.ktm.com/news-new-adventures-start-now-with-ktm?id=80395&l=uk&menueid=5904'),
(526,7,'Documented model and source history','{"summary":"KTM''s 5 March 2019 UK announcement confirms the arrival of the 790 Adventure and 790 Adventure R at authorised dealerships and describes their 799 cc LC8c twin platform.","source_name":"KTM official documentary material","source_url":"https://press.ktm.com/news-new-adventures-start-now-with-ktm?id=80395&l=uk&menueid=5904","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://press.ktm.com/news-new-adventures-start-now-with-ktm?id=80395&l=uk&menueid=5904'),
(951,1,'Model introduction','{"summary":"The Bullet 500 is an older-generation Royal Enfield single-cylinder motorcycle and should not be conflated with the latest Bullet 350.","source_name":"Royal Enfield official documentary material","source_url":"https://www.royalenfield.com/uk/en/support/owners-manual/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.royalenfield.com/uk/en/support/owners-manual/'),
(951,7,'Documented model and source history','{"summary":"Royal Enfield''s UK support library retains a separate Bullet 500 owner''s manual category, evidence of a distinct historic model identity; the page is not a production-date or technical fact source.","source_name":"Royal Enfield official documentary material","source_url":"https://www.royalenfield.com/uk/en/support/owners-manual/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.royalenfield.com/uk/en/support/owners-manual/'),
(960,1,'Model introduction','{"summary":"The Classic 500 is an earlier single-cylinder Royal Enfield classic road motorcycle, separate from the newer J-series Classic 350.","source_name":"Royal Enfield official documentary material","source_url":"https://www.royalenfield.com/uk/en/support/owners-manual/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.royalenfield.com/uk/en/support/owners-manual/'),
(960,7,'Documented model and source history','{"summary":"Royal Enfield''s UK support library lists a distinct Classic 500 owner''s manual. Year-by-year engine, equipment and emissions information must be taken from the exact manual and market edition.","source_name":"Royal Enfield official documentary material","source_url":"https://www.royalenfield.com/uk/en/support/owners-manual/","source_verification_status":"pending_review","editorial_status":"draft","editorial_note":"Internal source-capture summary. Independent source audit, exact model year/market and editorial signoff are required before public release. No images or rights approved."}'::jsonb,'https://www.royalenfield.com/uk/en/support/owners-manual/')) v(model_id,section_number,section_title,content,source_url);
 GET DIAGNOSTICS inserted=ROW_COUNT;
 IF inserted<>26 THEN RAISE EXCEPTION 'Expected 26 private sections, inserted %',inserted; END IF;
 SELECT count(*) INTO after_pub FROM public.motorcycle_universal_published_sections_v1;
 IF before_pub<>after_pub THEN RAISE EXCEPTION 'Public universal projection changed'; END IF;
END $$;
